import { normalizeDueDate } from '../due-date.js';

function foldASCII(value) {
  return value.replace(/[A-Z]/g, letter => letter.toLowerCase());
}

export function matchesSearch(value, query) {
  return foldASCII(value).includes(foldASCII(query.trim()));
}

export function filterProjects(projects, archiveFilter, query = '') {
  return projects.filter(project =>
    Boolean(project.archived) === (archiveFilter === 'archived') &&
    matchesSearch(project.name, query));
}

export function normalizeDueRange(from, through) {
  const normalizedFrom = normalizeDueDate(from);
  const normalizedThrough = normalizeDueDate(through);
  if (normalizedFrom === null || normalizedThrough === null) {
    throw new Error('Due range must use valid YYYY-MM-DD dates');
  }
  if (normalizedFrom && normalizedThrough && normalizedFrom > normalizedThrough) {
    throw new Error('Due from must not be after Due through');
  }
  return { from: normalizedFrom, through: normalizedThrough };
}

export function filterTasks(tasks, completion, priority, range = { from: '', through: '' }, query = '') {
  return tasks.filter(task =>
    (completion === 'all' || (completion === 'completed' ? task.completed : !task.completed)) &&
    (priority === 'all' || task.priority === priority) &&
    ((!range.from && !range.through) || (Boolean(task.due_date) &&
      (!range.from || task.due_date >= range.from) &&
      (!range.through || task.due_date <= range.through))) &&
    matchesSearch(task.title || '', query));
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { matchesSearch, filterProjects, filterTasks } from '../public/task-filters.js';

test('search trims query edges, preserves internal whitespace and ignores only ASCII case', () => {
  assert.equal(matchesSearch('Quarterly ROAD map', '\t road \n'), true);
  assert.equal(matchesSearch('ROAD  map', 'road map'), false);
  assert.equal(matchesSearch('ROAD  map', ' road  MAP '), true);
  assert.equal(matchesSearch('Résumé', 'résumé'), true);
  assert.equal(matchesSearch('Résumé', 'RÉSUMÉ'), false);
  assert.equal(matchesSearch('Item [One]', '[oNE]'), true);
  assert.equal(matchesSearch('Anything', ' \t\n '), true);
  assert.equal(matchesSearch('Anything', 'missing'), false);
});

test('project search intersects archive status, retains order and all-task summaries', () => {
  const projects = [
    { id: 1, name: 'Alpha plan', archived: 0, total: 4, completed: 2 },
    { id: 2, name: 'Other', archived: 0, total: 1, completed: 0 },
    { id: 3, name: 'ALPHA archive', archived: 1, total: 7, completed: 6 },
    { id: 4, name: 'Another alpha', archived: 0, total: 0, completed: 0 },
  ];
  const original = structuredClone(projects);
  const query = ' Alpha ';
  assert.deepEqual(filterProjects(projects, 'active', query), [projects[0], projects[3]]);
  assert.deepEqual(filterProjects(projects, 'archived', query), [projects[2]]);
  assert.deepEqual(filterProjects(projects, 'active', ''), [projects[0], projects[1], projects[3]]);
  assert.deepEqual(filterProjects(projects, 'active', 'absent'), []);
  assert.deepEqual(projects, original);
  projects[0].archived = 1;
  assert.deepEqual(filterProjects(projects, 'archived', query), [projects[0], projects[2]]);
  projects[0].archived = 0;
  assert.deepEqual(filterProjects(projects, 'active', query), [projects[0], projects[3]]);
});

test('task search intersects every completion, priority and due-range combination without changing data', () => {
  const tasks = [
    { id: 1, title: 'Plan first', completed: false, priority: 'High', due_date: '' },
    { id: 2, title: 'Second PLAN', completed: true, priority: 'Normal', due_date: '2026-05-01' },
    { id: 3, title: 'Unrelated', completed: false, priority: 'High', due_date: '2026-05-15' },
    { id: 4, title: 'Plan  fourth', completed: false, priority: 'High', due_date: '2026-05-31' },
    { id: 5, title: 'Plan fifth', completed: true, priority: 'Low', due_date: '2026-06-01' },
  ];
  const original = structuredClone(tasks);
  for (const completion of ['all', 'open', 'completed']) {
    for (const priority of ['all', 'Low', 'Normal', 'High']) {
      for (const range of [
        { from: '', through: '' },
        { from: '2026-05-01', through: '2026-05-31' },
        { from: '', through: '2026-05-01' },
        { from: '2026-05-31', through: '' },
      ]) {
        const otherMatches = filterTasks(tasks, completion, priority, range);
        assert.deepEqual(filterTasks(tasks, completion, priority, range, ' pLaN '),
          otherMatches.filter(task => task.id !== 3));
        assert.deepEqual(filterTasks(tasks, completion, priority, range, ' '), otherMatches);
      }
    }
  }
  assert.deepEqual(tasks, original);
});

test('edits and creation re-evaluate an applied query alongside unchanged filters', () => {
  const tasks = [
    { id: 1, title: 'Ship first', completed: false, priority: 'High', due_date: '2026-05-01' },
    { id: 2, title: 'Other second', completed: false, priority: 'High', due_date: '2026-05-31' },
  ];
  const range = { from: '2026-05-01', through: '2026-05-31' };
  const visible = () => filterTasks(tasks, 'open', 'High', range, 'ship').map(task => task.id);
  assert.deepEqual(visible(), [1]);
  tasks[1].title = 'SHIP second';
  assert.deepEqual(visible(), [1, 2]);
  tasks[0].title = 'Other first';
  assert.deepEqual(visible(), [2]);
  tasks[1].completed = true;
  assert.deepEqual(visible(), []);
  tasks[1].completed = false;
  tasks[1].priority = 'Low';
  assert.deepEqual(visible(), []);
  tasks[1].priority = 'High';
  tasks[1].due_date = '';
  assert.deepEqual(visible(), []);
  tasks[1].due_date = '2026-05-15';
  tasks.push({ id: 3, title: 'Ship third', completed: false, priority: 'High', due_date: '2026-05-20' });
  assert.deepEqual(visible(), [2, 3]);
  tasks.splice(1, 1); // Moving the matching task out retains remaining order.
  assert.deepEqual(visible(), [3]);
  assert.deepEqual(range, { from: '2026-05-01', through: '2026-05-31' });
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { filterTasks, normalizeDueRange } from '../public/task-filters.js';

test('due ranges validate both boundaries before replacing the applied range', () => {
  assert.deepEqual(normalizeDueRange(' \t0001-01-01 ', ' 9999-12-31\n'),
    { from: '0001-01-01', through: '9999-12-31' });
  assert.deepEqual(normalizeDueRange(' ', '\t'), { from: '', through: '' });
  assert.deepEqual(normalizeDueRange('2000-02-29', ''), { from: '2000-02-29', through: '' });
  assert.deepEqual(normalizeDueRange('', '2000-02-29'), { from: '', through: '2000-02-29' });
  let applied = normalizeDueRange('2026-01-01', '2026-12-31');
  for (const invalid of ['2026-02-29', '1900-02-29', '0000-01-01', '10000-01-01', '2026-1-01', '2026-04-31']) {
    for (const boundaries of [[invalid, ''], ['', invalid], ['9999-12-31', invalid]]) {
      assert.throws(() => { applied = normalizeDueRange(...boundaries); },
        { message: 'Due range must use valid YYYY-MM-DD dates' });
      assert.deepEqual(applied, { from: '2026-01-01', through: '2026-12-31' });
    }
  }
  assert.throws(() => { applied = normalizeDueRange('2026-12-31', '2026-01-01'); },
    { message: 'Due from must not be after Due through' });
  assert.deepEqual(applied, { from: '2026-01-01', through: '2026-12-31' });
});

test('inclusive and unbounded due ranges intersect completion and priority, retaining order and data', () => {
  const tasks = [
    { id: 1, completed: false, priority: 'High', due_date: '' },
    { id: 2, completed: true, priority: 'Low', due_date: '0001-01-01' },
    { id: 3, completed: false, priority: 'High', due_date: '2024-02-29' },
    { id: 4, completed: true, priority: 'Normal', due_date: '2024-03-01' },
    { id: 5, completed: false, priority: 'Low', due_date: '9999-12-31' },
    { id: 6, completed: true, priority: 'High', due_date: '2024-02-29' },
  ];
  const original = structuredClone(tasks);
  const ranges = [
    ['', '', [1, 2, 3, 4, 5, 6]],
    ['0001-01-01', '9999-12-31', [2, 3, 4, 5, 6]],
    ['2024-02-29', '2024-03-01', [3, 4, 6]],
    ['2024-02-29', '2024-02-29', [3, 6]],
    ['', '2024-02-29', [2, 3, 6]],
    ['2024-03-01', '', [4, 5]],
    ['2025-01-01', '2025-12-31', []],
  ];
  for (const [from, through, dateIds] of ranges) {
    for (const completion of ['all', 'open', 'completed']) {
      for (const priority of ['all', 'Low', 'Normal', 'High']) {
        const expected = filterTasks(tasks, completion, priority).filter(task => dateIds.includes(task.id));
        assert.deepEqual(filterTasks(tasks, completion, priority, normalizeDueRange(from, through)), expected);
      }
    }
  }
  assert.deepEqual(tasks, original);
});

test('task edits re-evaluate all three filters using the same applied range', () => {
  const tasks = [
    { id: 1, title: 'First', completed: false, priority: 'High', due_date: '2026-03-01' },
    { id: 2, title: 'Second', completed: false, priority: 'High', due_date: '' },
  ];
  const range = normalizeDueRange('2026-03-01', '2026-03-31');
  const visible = () => filterTasks(tasks, 'open', 'High', range).map(task => task.id);
  assert.deepEqual(visible(), [1]);
  tasks[1].due_date = '2026-03-31';
  assert.deepEqual(visible(), [1, 2]);
  tasks[0].title = 'Renamed';
  assert.deepEqual(visible(), [1, 2]);
  tasks[0].due_date = '2026-04-01';
  assert.deepEqual(visible(), [2]);
  tasks[1].completed = true;
  assert.deepEqual(visible(), []);
  tasks[1].completed = false;
  tasks[1].priority = 'Low';
  assert.deepEqual(visible(), []);
  tasks[1].priority = 'High';
  assert.deepEqual(visible(), [2]);
  tasks[1].due_date = '';
  assert.deepEqual(visible(), []);
  assert.deepEqual(range, { from: '2026-03-01', through: '2026-03-31' });
});

test('all combinations of completion and priority filters preserve creation order and saved data', () => {
  const tasks = [
    { id: 1, title: 'High open', completed: false, priority: 'High' },
    { id: 2, title: 'Low completed', completed: true, priority: 'Low' },
    { id: 3, title: 'Normal open', completed: false, priority: 'Normal' },
    { id: 4, title: 'High completed', completed: true, priority: 'High' },
    { id: 5, title: 'Low open', completed: false, priority: 'Low' },
    { id: 6, title: 'Normal completed', completed: true, priority: 'Normal' },
  ];
  const original = structuredClone(tasks);
  const expected = {
    all: { all: [1, 2, 3, 4, 5, 6], Low: [2, 5], Normal: [3, 6], High: [1, 4] },
    open: { all: [1, 3, 5], Low: [5], Normal: [3], High: [1] },
    completed: { all: [2, 4, 6], Low: [2], Normal: [6], High: [4] },
  };
  for (const [completion, priorities] of Object.entries(expected)) {
    for (const [priority, ids] of Object.entries(priorities)) {
      assert.deepEqual(filterTasks(tasks, completion, priority).map(task => task.id), ids,
        `${completion} and ${priority}`);
    }
  }
  assert.deepEqual(tasks, original);
});

test('edits re-evaluate both filters without changing order, and rename preserves membership', () => {
  const tasks = [
    { id: 1, title: 'First', completed: false, priority: 'High' },
    { id: 2, title: 'Second', completed: false, priority: 'High' },
    { id: 3, title: 'Third', completed: true, priority: 'Low' },
  ];
  const visible = () => filterTasks(tasks, 'open', 'High').map(task => task.id);
  assert.deepEqual(visible(), [1, 2]);
  tasks[0].title = 'Renamed';
  assert.deepEqual(visible(), [1, 2]);
  tasks[0].priority = 'Normal';
  assert.deepEqual(visible(), [2]);
  tasks[1].completed = true;
  assert.deepEqual(visible(), []);
  tasks[0].priority = 'High';
  tasks[1].completed = false;
  assert.deepEqual(visible(), [1, 2]);
  assert.equal(tasks.filter(task => task.completed).length, 1);
  assert.equal(tasks.length, 3);
});

import { filterProjects, filterTasks, normalizeDueRange } from './task-filters.js';

const app = document.getElementById('app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function showError(message) {
  let alert = document.getElementById('error');
  if (!alert) {
    alert = document.createElement('p');
    alert.id = 'error';
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
  alert.hidden = false;
}

function projectRow(project, onArchive) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    document.getElementById('error').hidden = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      onArchive(saved);
    } catch (error) { showError(error.message); }
    finally { archive.disabled = false; }
  });
  row.append(name, summary, open, archive);
  return row;
}

async function renderProject(projectId) {
  const project = await request(`/api/projects/${projectId}`);
  let tasks = await request(`/api/projects/${projectId}/tasks`);
  const destinations = (await request('/api/projects')).filter(candidate =>
    !candidate.archived && candidate.id !== project.id);
  app.innerHTML = `
    <button type="button" id="back">Projects</button><h1></h1>
    <form id="rename-form">
      <label for="new-project-name">New project name</label>
      <div class="form-controls">
        <input id="new-project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Rename project</button>
      </div>
    </form>
    <div class="project-default">
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority">
        <option value="Low">Low</option>
        <option value="Normal">Normal</option>
        <option value="High">High</option>
      </select>
    </div>
    <form id="task-form">
